<template><aside class="search-keyboard"><div class="keyboard-title"><Keyboard :size="18"/><b>{{title}}</b></div><div class="keyboard-value"><span>{{modelValue||'输入拼音首字母'}}</span><button aria-label="退格" @click="edit(modelValue.slice(0,-1))"><Delete :size="20"/></button><button aria-label="清空" @click="edit('')"><X :size="18"/></button></div><div class="keyboard-modes"><button :class="{on:!numeric}" @click="numeric=false">ABC 首字母</button><button :class="{on:numeric}" @click="numeric=true">123 数字</button></div><div class="key-grid"><button v-for="key in keys" :key="key" @click="edit(modelValue+key)">{{key}}</button></div><div class="keyboard-bottom"><button @click="$emit('system')">系统输入</button><button @click="$emit('submit')" class="confirm">搜索 <ArrowRight :size="17"/></button></div><p>支持触屏和遥控器操作</p></aside></template>
<script setup>
import {computed,ref} from 'vue';import {Keyboard,Delete,X,ArrowRight} from 'lucide-vue-next'
const props=defineProps({modelValue:{type:String,default:''},title:{type:String,default:'快速找歌'}}),emit=defineEmits(['update:modelValue','submit','system']),numeric=ref(false),keys=computed(()=>numeric.value?'1234567890'.split(''):'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split(''));function edit(value){emit('update:modelValue',value.slice(0,80))}
</script><style scoped>
.search-keyboard{background:var(--panel);border:1px solid var(--glass-border);border-radius:14px;padding:16px;align-self:start;position:sticky;top:0}.keyboard-title{display:flex;gap:9px;align-items:center;color:var(--dim);font-size:13px;margin-bottom:14px}.keyboard-value{display:flex;align-items:center;gap:9px;border-bottom:1px solid var(--line);padding-bottom:12px;min-height:35px}.keyboard-value>span{font-size:13px;color:var(--gold);flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.keyboard-value button{color:var(--dim);padding:4px}.keyboard-modes{display:flex;gap:9px;margin:12px 0}.keyboard-modes button{font-size:11px;color:var(--dim2);padding:7px 9px;border-radius:7px}.keyboard-modes button.on{background:var(--gold-glow);color:var(--gold)}.key-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:7px}.key-grid button{height:35px;border:1px solid var(--glass-border);background:var(--panel2);font-size:16px;border-radius:7px;color:var(--text)}.key-grid button:hover{background:var(--gold);color:var(--bg)}.keyboard-bottom{display:flex;gap:9px;margin-top:14px}.keyboard-bottom button{min-height:35px;flex:1;font-size:12px;background:var(--panel2);border-radius:8px}.keyboard-bottom .confirm{background:var(--gold);color:var(--bg);display:flex;gap:10px;justify-content:center;align-items:center}.search-keyboard p{font-size:9px;text-align:center;color:var(--dim2);margin:12px 0 0}
</style>
<style scoped>.search-keyboard{padding:12px}.keyboard-title{margin-bottom:8px}.keyboard-value{padding-bottom:7px;min-height:29px}.keyboard-modes{margin:8px 0}.keyboard-modes button{padding:5px 8px;font-size:10px}.key-grid{gap:5px}.key-grid button{height:30px;font-size:15px}.keyboard-bottom{margin-top:10px}.keyboard-bottom button{min-height:31px}.search-keyboard p{display:none}</style>
